import sys; sys.path.insert(0, '.')
from docx_helpers import *
def build(path):
    d = Doc('How to read the output files', 'Jalour Developments  |  INTERNAL guide. Do not send to investors.')
    d.p('INTERNAL GUIDE. NOT PART OF ANY INVESTOR PACK.', bold=True, size=10, color=RGBColor(0xA2, 0x3B, 0x3B))
    d.p('How to read the output files', bold=True, size=22, color=NAVY, after=4)
    d.p('Jalour investor packs for Green Square and L\'avenir. All figures are in EGP million unless stated. All returns are projections, not guarantees.')
    d.h2('1. What is in the output folder')
    d.table([['Folder or file', 'What it is', 'Who may see it'],
             ['COMBINED_125M', 'The pack for an investor paying EGP 125M: EGP 62.5M in each project. Shows both projects.', 'That investor, after signing the NDA'],
             ['GS_050M, GS_075M, GS_100M', 'Green Square packs for tickets of 50, 75 and 100M. Name only Green Square.', 'That project\'s investor only'],
             ['LA_050M, LA_075M, LA_100M', 'L\'avenir packs for tickets of 50, 75 and 100M. Name only L\'avenir.', 'That project\'s investor only'],
             ['00_Model_Reconciliation, 01_Structuring_*, 02_Open_Items_Register', 'Internal working papers: how the source model was checked, the structure analysis, and the list of open items.', 'Jalour only'],
             ['INTERNAL_Disclosure_QA.docx', 'What the team may and may not say to investors about other investors and projects.', 'Jalour only'],
             ['QA_Reports', 'Test results for every pack (numbers tie out, independent recalculation, disclosure scan).', 'Jalour only']], [4.6, 7.8, 3.9], 'Output folder', -1, font=9)
    d.h2('2. The files inside each pack')
    d.table([['File', 'Formats', 'Read it for'], ['Deck', '.pptx and .pdf', 'The 17 to 18 slide presentation: terms, market, project, cash flow, returns, risks, next steps. Start here.'], ['Investment_Memo', '.docx and .pdf', 'The full 28 to 35 page memorandum. Section 1 is the summary; sections 12 to 14 give the terms, returns and security; section 17 the risks.'], ['DD_Memo', '.docx and .pdf', 'The due diligence memorandum: what documents exist, what is pending, red flags, open items.'], ['Financial_Annex', '.xlsx', 'The workbook behind every number in the deck and memos. Open this to check or change a figure.'], ['NDA_Template', '.docx and .pdf', 'The non-disclosure agreement to sign before sponsor, permit, title and landlord materials are shared. For counsel review.']], [3.6, 3.0, 9.7], 'Files in a pack', -1, font=9.5)
    d.h2('3. How to read the Financial Annex (Excel)')
    d.p('Colour code: blue text is an input you can change; black text is a formula. Change an input on the Inputs sheet or the blue scenario parameters and every sheet recalculates. Do not type over black cells.')
    d.table([['Sheet', 'What it shows'], ['Cover', 'Title, confidentiality statement, status and sheet list.'], ['Summary (single packs) or Combined_Summary (combined pack)', 'The headline figures used in the deck and memos: ticket, net cash flow, NPV, peak shortage, Option A and Option B returns. The reference sheet.'], ['Inputs', 'Every assumption with its source or basis.'], ['Source_Data', 'Quarterly sales, collections and costs taken from the Jalour model.'], ['Project_CF', 'Quarterly project cash flow: collections less landlord payments, construction, commission and SG&A. Net cash flow, cumulative position and NPV at 14%.'], ['Sources_Uses', 'What the money is used for at the funding peak and where it comes from. The balance is shown as Jalour sponsor equity, project collections and other capital sources.'], ['Option_A', 'Units option: face value (2.0x), resale at delivery list, investor cash flows, IRR and multiple, and the cost to Jalour.'], ['Option_B', 'Cash option: 2.3x in 12 quarterly instalments after a 24-month grace period, coverage tests and pooled cash.'], ['Scenarios', 'Downside, upside, cost overrun, collections slip and delivery payments at handover.'], ['Sensitivity', 'Price, delay, cost and slip sensitivities.'], ['Reconciliation', 'Checks against the source model and an independent recomputation. Every difference should be zero.'], ['Combined pack only', 'Project sheets carry the prefix GS_ or LA_. Combined_Position adds the two projects together; Combined_Reconciliation checks both.']], [5.6, 10.7], 'Annex sheets', -1, font=9)
    d.h2('4. Key terms')
    d.table([['Term', 'Meaning'], ['Option A (units)', 'The investor receives units with a face value of 2.0x the ticket, priced at the launch list, and resells them after handover.'], ['Option B (cash)', 'The investor receives 2.3x the ticket in 12 equal quarterly instalments after a 24-month grace period.'], ['IRR', 'Annual internal rate of return of the investor\'s cash flows. MOIC is cash received divided by cash invested.'], ['NPV', 'Value today of Jalour\'s net cash flow, discounted at 14% a year.'], ['Peak shortage', 'The lowest cumulative net cash flow before any investor money. It is the project\'s maximum funding need.'], ['Pooled cash', 'Project cash plus the ticket less payouts. Nothing is ring-fenced.'], ['Coverage', 'Cash available to pay an instalment divided by the instalment. Two versions: net cash flow only (strict) and pooled cash.'], ['Base, downside, upside', 'Downside: sales 12 months later and prices 10% lower. Upside: prices 10% higher. Handover case: delivery payments arrive at handover, not before.'], ['[After NDA]', 'Information provided only once the investor has signed the NDA.']], [4.2, 12.1], 'Terms', -1, font=9.5)
    d.h2('5. How to check a number')
    d.numbered(['Find the figure in the deck or memo and note its label and case (base, downside, upside).', 'Open Financial_Annex.xlsx and go to Summary (or Combined_Summary). The same figure is there, and the cell links back to the calculation sheet.', 'Click the cell to see its formula and follow it to Project_CF, Option_A or Option_B.', 'Open the matching QA report in QA_Reports to see the tie-out and the independent recalculation.'])
    d.h2('6. Rules for sharing')
    d.bullets(['Everything in every pack is confidential and subject to the NDA. Send the NDA first.', 'Send each investor only their own pack. The six single-project packs must never be sent with, or mention, the other project.', 'Keep the files in this guide, QA_Reports, the 00, 01 and 02 working papers and INTERNAL_Disclosure_QA.docx inside Jalour.', 'Send the PDF versions to investors who only need to read; send the Excel annex to those who want to test the numbers.'])
    d.save(path)
if __name__ == '__main__': build(sys.argv[1]); print('ok')
